186		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
187		var problems []string
188		problems = append(problems, parseErrs...)
189	
190		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
191		var ordered []*parsedRow
192		newCount, dupCount := 0, 0
193	
194		for _, r := range rows {
