198				continue
199			}
200			// 金额可行性预检：数量×固定单价不得溢出（金额单位：分）。
201			if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
202				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
203				continue
204			}
205	
206			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
207			var existing *usageRecord
208			if inStore, ok := s.Usage[r.rec.ID]; ok {
209				existing = inStore
210			} else if inBatch, ok := accepted[r.rec.ID]; ok {
211				existing = &inBatch.rec
212			}
213	
214			if existing != nil {
215				if !sameUsage(existing, &r.rec, r.t) {
216					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
217						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
218					continue
219				}
220				dupCount++
221				continue
222			}
223	
224			// 全新标识：不得进入该客户已封账的 UTC 自然月。
225			month := r.t.UTC().Format("2006-01")
226			if s.sealed(r.rec.CustomerID, month) {
227				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
228					r.line, r.rec.CustomerID, month, r.rec.ID))
229				continue
230			}
231	
232			rr := r
233			accepted[r.rec.ID] = rr
234			ordered = append(ordered, rr)
235			newCount++
236		}
237	
238		if len(problems) > 0 {
239			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
240		}
241	
242		for _, r := range ordered {
243			rec := r.rec
244			s.Usage[rec.ID] = &rec
245		}
246		if err := s.save(); err != nil {
247			return err
248		}
249		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
250		return nil
251	}
