253	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
254	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
255		cr := csv.NewReader(r)
256		cr.FieldsPerRecord = 4
257		cr.TrimLeadingSpace = true
258	
259		header, err := cr.Read()
260		if err == io.EOF {
261			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
262		}
263		if err != nil {
264			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
265		}
266		for i := range header {
267			header[i] = strings.TrimSpace(header[i])
268		}
269		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
270			header[2] != "time" || header[3] != "quantity" {
271			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
272		}
273	
274		var rows []*parsedRow
275		var problems []string
276		line := 1
277		for {
278			rec, err := cr.Read()
279			if err == io.EOF {
280				break
281			}
282			line++
283			if err != nil {
284				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
285				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
286					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
287					break
288				}
289				continue
290			}
291			for i := range rec {
292				rec[i] = strings.TrimSpace(rec[i])
293			}
294	
295			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
296			if id == "" {
297				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
298				continue
299			}
300			if custID == "" {
301				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
302				continue
303			}
304			t, err := time.Parse(time.RFC3339, ts)
305			if err != nil {
306				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
307				continue
308			}
309			qty, err := strconv.ParseInt(qtyText, 10, 64)
310			if err != nil {
311				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
312				continue
313			}
314			if qty <= 0 {
315				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
316				continue
317			}
318	
319			rows = append(rows, &parsedRow{
320				line: line,
321				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
322				t:    t,
323			})
324		}
325		return rows, problems
326	}
