328	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
329	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
330	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
331		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
332			return false
333		}
334		et, err := time.Parse(time.RFC3339, existing.Time)
335		if err != nil {
336			return existing.Time == candidate.Time
337		}
338		return et.Equal(candidateT)
339	}
