359	func cmdBillSettle(dir, customerID, month string) error {
360		if !validMonth(month) {
361			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
362		}
363		s, err := loadStore(dir)
364		if err != nil {
365			return err
366		}
367		cust, ok := s.Customers[customerID]
368		if !ok {
369			return fmt.Errorf("客户标识 %q 不存在", customerID)
370		}
371	
372		key := billKey(customerID, month)
373		if existing, ok := s.Bills[key]; ok {
374			// 幂等：同一客户同一月份重复结算，直接返回原账单，
375			// 不重新计费、不产生新账单或调整、不落盘。
376			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
377			printBill(existing, cust, adjustmentsFor(s, customerID, month), paymentsFor(s, customerID, month))
378			return nil
379		}
380	
381		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
382		var inMonthRecs []*usageRecord
383		for _, u := range s.Usage {
384			if u.CustomerID == customerID && inMonth(u.Time, month) {
385				inMonthRecs = append(inMonthRecs, u)
386			}
387		}
388		if len(inMonthRecs) == 0 {
389			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
390		}
391		sortByInstant(inMonthRecs)
392	
393		lines := make([]billLine, 0, len(inMonthRecs))
394		var totalQty, totalFee int64
395		for _, u := range inMonthRecs {
396			lineFee, err := mul64(u.Quantity, cust.Price)
397			if err != nil {
398				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
399			}
400			totalQty, err = add64(totalQty, u.Quantity)
401			if err != nil {
402				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
403			}
404			totalFee, err = add64(totalFee, lineFee)
405			if err != nil {
406				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
407			}
408			lines = append(lines, billLine{
409				UsageID:  u.ID,
410				Time:     u.Time,
411				Quantity: u.Quantity,
412				LineFee:  lineFee,
413			})
414		}
415	
416		b := &bill{
417			ID:         stableBillID(customerID, month),
418			CustomerID: customerID,
419			Month:      month,
420			TotalQty:   totalQty,
421			UnitPrice:  cust.Price,
422			TotalFee:   totalFee,
423			Lines:      lines,
424			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
425		}
426		s.Bills[key] = b
427	
428		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
429		if err := s.save(); err != nil {
430			delete(s.Bills, key)
431			return err
432		}
433		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
434		printBill(b, cust, nil, nil)
435		return nil
436	}
