552	// paymentHistoryEvents 把收款登记与撤销展开为按操作序号排序的可读历史条目；
553	// month 为当前展示账单所在月份，用于给出该收款在本账单的分配。
554	func paymentHistoryEvents(pays []*payment, month string) []string {
555		type event struct {
556			seq  int64
557			text string
558		}
559		var events []event
560		for _, p := range pays {
561			alloc := p.amountFor(month)
562			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
563				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
564			if p.Revoked {
565				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
566					p.ID, p.RevokeReason, p.ID, p.Total, alloc)})
567			}
568		}
569		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
570		out := make([]string, len(events))
571		for i, ev := range events {
572			out[i] = ev.text
573		}
574		return out
575	}
576	
577	func paymentStatus(p *payment) string {
578		if p.Revoked {
579			return "已撤销"
580		}
581		return "实收中"
582	}
