597	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
598		if !validMonth(month) {
599			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
600		}
601		if strings.TrimSpace(adjID) == "" {
602			return fmt.Errorf("调整标识不能为空")
603		}
604		amount, err := parseAmount(amountText)
605		if err != nil {
606			return err
607		}
608		if strings.TrimSpace(reason) == "" {
609			return fmt.Errorf("调整原因不能为空")
610		}
611	
612		s, err := loadStore(dir)
613		if err != nil {
614			return err
615		}
616		if _, ok := s.Customers[customerID]; !ok {
617			return fmt.Errorf("客户标识 %q 不存在", customerID)
618		}
619		b, ok := s.Bills[billKey(customerID, month)]
620		if !ok {
621			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
622		}
623	
624		if existing, ok := s.Adjustments[adjID]; ok {
625			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
626			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
627			if existing.CustomerID == customerID && existing.Month == month &&
628				existing.Amount == amount && existing.Reason == reason {
629				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
630				printAdjustment(existing, s)
631				return nil
632			}
633			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
634				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
635		}
636	
637		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
638		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
639		// 不占用该调整标识。
640		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
641		if err != nil {
642			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
643		}
644		received, err := paymentReceived(paymentsFor(s, customerID, month), month)
645		if err != nil {
646			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
647		}
648		newPayable, err := addSigned64(payable, amount)
649		if err != nil {
650			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
651		}
652		if newPayable < 0 {
653			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
654		}
655		if newPayable < received {
656			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
657				newPayable, received, payable, amount)
658		}
659	
660		a := &adjustment{
661			ID:         adjID,
662			CustomerID: customerID,
663			Month:      month,
664			Amount:     amount,
665			Reason:     reason,
666			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
667		}
668		s.NextSeq++
669		a.Seq = s.NextSeq
670		s.Adjustments[adjID] = a
671	
672		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
673		// 该调整标识不被占用。
674		if err := s.save(); err != nil {
675			delete(s.Adjustments, adjID)
676			s.NextSeq--
677			return err
678		}
679		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
680			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
681		printAdjustment(a, s)
682		return nil
683	}
684	
685	func cmdBillRevoke(dir, adjID, reason string) error {
686		if strings.TrimSpace(adjID) == "" {
687			return fmt.Errorf("调整标识不能为空")
688		}
689		if strings.TrimSpace(reason) == "" {
690			return fmt.Errorf("撤销原因不能为空")
691		}
692	
693		s, err := loadStore(dir)
694		if err != nil {
695			return err
696		}
697		a, ok := s.Adjustments[adjID]
698		if !ok {
699			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
700		}
701	
702		if a.Revoked {
703			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
704			// 改用其他原因则拒绝。
705			if a.RevokeReason == reason {
706				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
707				printAdjustment(a, s)
708				return nil
709			}
710			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
711		}
712	
713		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
714		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
715		// 改变余额后重试。
716		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
717		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
718		if err != nil {
719			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
720		}
721		received, err := paymentReceived(paymentsFor(s, a.CustomerID, a.Month), a.Month)
722		if err != nil {
723			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
724		}
725		neg, err := neg64(a.Amount)
726		if err != nil {
727			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
728		}
729		newPayable, err := addSigned64(payable, neg)
730		if err != nil {
731			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
732				payable, a.Amount)
733		}
734		if newPayable < 0 {
735			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
736				newPayable, payable, a.Amount)
737		}
738		if newPayable < received {
739			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
740				newPayable, received, payable, a.Amount)
741		}
742	
743		a.Revoked = true
744		a.RevokeReason = reason
745		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
746		s.NextSeq++
747		a.RevokeSeq = s.NextSeq
748	
749		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
750		if err := s.save(); err != nil {
751			a.Revoked = false
752			a.RevokeReason = ""
753			a.RevokedAt = ""
754			a.RevokeSeq = 0
755			s.NextSeq--
756			return err
757		}
758		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
759			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
760		printAdjustment(a, s)
761		return nil
762	}
763	
764	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
765	func printAdjustment(a *adjustment, s *state) {
766		b := s.Bills[billKey(a.CustomerID, a.Month)]
767		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
768		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
769		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
770		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
771		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
772		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
773		if a.Revoked {
774			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
775		} else {
776			fmt.Fprintf(stdout, "当前状态：生效中\n")
777		}
778		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
779	}
780	
781	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
782	func parsePositiveAmount(text string) (int64, error) {
783		text = strings.TrimSpace(text)
784		amount, err := strconv.ParseInt(text, 10, 64)
785		if err != nil {
786			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
787		}
788		if amount <= 0 {
789			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
790		}
791		return amount, nil
792	}
793	
794	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
795		if !validMonth(month) {
796			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
797		}
798		amount, err := parsePositiveAmount(amountText)
799		if err != nil {
800			return err
801		}
802		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
803		return registerPayment(dir, customerID, payID, amount, note,
804			[]paymentAllocation{{Month: month, Amount: amount}})
805	}
806	
807	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
808		total, err := parsePositiveAmount(totalText)
809		if err != nil {
810			return err
811		}
812		allocs, err := parseAllocations(allocArgs)
813		if err != nil {
814			return err
815		}
816		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
817		var sum int64
818		for _, al := range allocs {
819			sum, err = add64(sum, al.Amount)
820			if err != nil {
821				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
822			}
823		}
824		if sum != total {
825			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
826		}
827		return registerPayment(dir, customerID, payID, total, note, allocs)
828	}
829	
830	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
831	// 月份不得重复，每项金额为正整数分。
832	func parseAllocations(args []string) ([]paymentAllocation, error) {
833		if len(args) == 0 {
834			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
835		}
836		seen := make(map[string]bool)
837		allocs := make([]paymentAllocation, 0, len(args))
838		for _, arg := range args {
839			parts := strings.Split(arg, ":")
840			if len(parts) != 2 {
841				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
842			}
843			month := strings.TrimSpace(parts[0])
844			if !validMonth(month) {
845				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
846			}
847			if seen[month] {
848				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
849			}
850			seen[month] = true
851			amount, err := parsePositiveAmount(parts[1])
852			if err != nil {
853				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
854			}
855			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
856		}
857		return allocs, nil
858	}
859	
860	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
861	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
862	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
863		if strings.TrimSpace(payID) == "" {
864			return fmt.Errorf("收款标识不能为空")
865		}
866		if strings.TrimSpace(note) == "" {
867			return fmt.Errorf("收款备注不能为空")
868		}
869		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
870		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
871	
872		s, err := loadStore(dir)
873		if err != nil {
874			return err
875		}
876		if _, ok := s.Customers[customerID]; !ok {
877			return fmt.Errorf("客户标识 %q 不存在", customerID)
878		}
879		for _, al := range allocs {
880			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
881				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
882			}
883		}
884	
885		if existing, ok := s.Payments[payID]; ok {
886			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
887			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
888			// 已撤销的重放仍返回已撤销状态，不恢复实收。
889			if samePaymentContent(existing, customerID, total, note, allocs) {
890				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
891				printPayment(existing, s)
892				return nil
893			}
894			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
895				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
896		}
897	
898		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
899		for _, al := range allocs {
900			b := s.Bills[billKey(customerID, al.Month)]
901			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
902			if err != nil {
903				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
904			}
905			received, err := paymentReceived(paymentsFor(s, customerID, al.Month), al.Month)
906			if err != nil {
907				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
908			}
909			if payable == 0 {
910				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
911			}
912			if al.Amount > payable-received {
913				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
914					al.Amount, payable-received, customerID, al.Month, payable, received)
915			}
916		}
917	
918		p := &payment{
919			ID:          payID,
920			CustomerID:  customerID,
921			Total:       total,
922			Note:        note,
923			Allocations: allocs,
924			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
925		}
926		s.NextSeq++
927		p.Seq = s.NextSeq
928		s.Payments[payID] = p
929	
930		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
931		// 一切不生效，该收款标识不被占用。
932		if err := s.save(); err != nil {
933			delete(s.Payments, payID)
934			s.NextSeq--
935			return err
936		}
937		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
938		printAllocationBalances(s, p)
939		fmt.Fprintln(stdout)
940		printPayment(p, s)
941		return nil
942	}
943	
944	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
945	// 内容相同；分配顺序不影响身份。
946	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
947		if p.CustomerID != customerID || p.Total != total || p.Note != note {
948			return false
949		}
950		if len(p.Allocations) != len(allocs) {
951			return false
952		}
953		for _, al := range allocs {
954			if p.amountFor(al.Month) != al.Amount {
955				return false
956			}
957		}
958		return true
959	}
960	
961	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
962	func formatAllocations(allocs []paymentAllocation) string {
963		parts := make([]string, len(allocs))
964		for i, al := range allocs {
965			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
966		}
967		return strings.Join(parts, ",")
968	}
969	
970	// printAllocationBalances 输出该收款每个分配月份当前的实收与未收余额。
971	func printAllocationBalances(s *state, p *payment) {
972		for _, al := range p.Allocations {
973			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
974			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
975			received, _ := paymentReceived(paymentsFor(s, p.CustomerID, al.Month), al.Month)
976			fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，实收 %d 分（%s），未收余额 %d 分（%s）\n",
977				al.Month, al.Amount, received, moneyFen(received), payable-received, moneyFen(payable-received))
978		}
979	}
980	
981	func cmdBillUnpay(dir, payID, reason string) error {
982		if strings.TrimSpace(payID) == "" {
983			return fmt.Errorf("收款标识不能为空")
984		}
985		if strings.TrimSpace(reason) == "" {
986			return fmt.Errorf("撤销原因不能为空")
987		}
988	
989		s, err := loadStore(dir)
990		if err != nil {
991			return err
992		}
993		p, ok := s.Payments[payID]
994		if !ok {
995			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
996		}
997	
998		if p.Revoked {
999			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1000			// 改用其他原因则拒绝。
1001			if p.RevokeReason == reason {
1002				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1003				printPayment(p, s)
1004				return nil
1005			}
1006			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1007		}
1008	
1009		// 撤销整笔生效：取消该笔在全部分配月份上的实收，不接受部分撤销；
1010		// 不改变应付、其他收款或调整，原收款、分配与撤销原因永久保留。
1011		p.Revoked = true
1012		p.RevokeReason = reason
1013		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1014		s.NextSeq++
1015		p.RevokeSeq = s.NextSeq
1016	
1017		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1018		if err := s.save(); err != nil {
1019			p.Revoked = false
1020			p.RevokeReason = ""
1021			p.RevokedAt = ""
1022			p.RevokeSeq = 0
1023			s.NextSeq--
1024			return err
1025		}
1026		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s）：\n", payID, p.Total, moneyFen(p.Total))
1027		printAllocationBalances(s, p)
1028		fmt.Fprintln(stdout)
1029		printPayment(p, s)
1030		return nil
1031	}
1032	
1033	// printPayment 输出单笔收款记录：总额、全部分配与当前状态；
1034	// 各月应付/实收取自当前库状态。
1035	func printPayment(p *payment, s *state) {
1036		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1037		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1038		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1039		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1040		if p.Revoked {
1041			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1042		} else {
1043			fmt.Fprintf(stdout, "当前状态：实收中\n")
1044		}
1045		fmt.Fprintln(stdout, "分配明细：")
1046		for i, al := range p.Allocations {
1047			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1048			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1049			received, _ := paymentReceived(paymentsFor(s, p.CustomerID, al.Month), al.Month)
1050			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1051				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1052		}
1053	}
1054

