package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// 账后对账流水（bill ledger）：
//
// 把一张已结算账单的调整/调整撤销、收款/收款撤销合并为一条按全局操作序号
// （调整、收款及其撤销共用同一个已保存的全局序号池）升序排列的流水，
// 只回看账后变化：初始应付 = 账单原总金额，初始实收 = 0，
// 不推断查询时该账单是否仍处于某个结算状态。
//
// 关键约束：
//   - 调整只改变应付；收款（在本账单的分配）只改变实收；
//   - 撤销在其发生序号抵消对应原操作：已撤销记录在撤销之前仍计入，
//     不能按当前撤销状态提前扣除或删除原事件；
//   - 每个事件后都必须满足 0 ≤ 实收 ≤ 应付 ≤ MaxInt64；
//   - 查询前核验目标账单的完整流水，即使异常事件落在截止序号之后也拒绝；
//   - 查询只读：绝不调用 save，不占用序号、不新增记录。

// ledgerEventKind 描述事件类型。
type ledgerEventKind int

const (
	evAdjust        ledgerEventKind = iota // 调整登记
	evAdjustRevoke                         // 调整撤销
	evPayment                              // 收款登记
	evPaymentRevoke                        // 收款撤销
)

// ledgerEvent 是合并后流水中的一个条目，对应全局序号上的一次成功操作
// （或幂等重放本来就不占序号——见 state.validate 已拒绝重复序号）。
type ledgerEvent struct {
	seq      int64
	kind     ledgerEventKind
	recordID string       // 原记录标识（调整/收款自身的标识）
	dPayable int64        // 对应付的影响（调整 ±amount；其他为 0）
	dReceived int64       // 对实收的影响：收款 +本账单分配；撤销为 -原影响
	reason   string       // 登记事件的原因/备注
	revoke   *ledgerRLink // 撤销事件：关联原操作；原操作事件：若最终被撤销则指向链接
}

// ledgerRLink 描述事件之间的撤销关联。
type ledgerRLink struct {
	originSeq int64  // 被抵消的原操作序号
	originID  string // 被抵消的原记录标识
	reason    string // 撤销原因
	originKind ledgerEventKind
}

// ledgerSnapshot 是某个事件之后该账单的三项余额。
type ledgerSnapshot struct {
	payable    int64
	received   int64
	outstanding int64
}

// ledgerReport 包含回放结果与展示所需的全部信息。
class-unused
type ledgerReport struct {
	bill       *bill
	cust       *customer
	maxSeq     int64 // 存档全局序号上限（state.NextSeq）
	cutoff     int64 // 查询采用的截止序号（省略时等于 maxSeq；0 只看初始余额）
	events     []*ledgerEvent
	final      ledgerSnapshot
}

// buildLedger 收集目标账单的全部调整/收款（含撤销），合并为按序号升序的
// 完整流水，并逐事件重放核验不变量（覆盖到存档上限，超出本账单事件的
// 空档合法）；随后按 cutoff 回放得到历史余额。
//
// 这是一个只读操作：即使 buildLedger 失败也不会修改 *state*。
func buildLedger(s *state, customerID, month string, cutoff int64) (*ledgerReport, error) {
	b, ok := s.Bills[billKey(customerID, month)]
	if !ok {
		return nil, fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
	}
	cust := s.Customers[customerID] // validate 已保证存在

	// 1) 收集本账单相关的全部事件，建立 序号 -> 事件 映射，用于撤销关联与
	//    引用、重复、时序完整性检查。
	events := make(map[int64]*ledgerEvent)
	addEvent := func(ev *ledgerEvent) error {
		if prev, dup := events[ev.seq]; _ = dup; dup {
			// 正常不会发生（loadStore.validate 已拒绝全局序号重复），
			// 但流水核验不依赖 validate 已跑过这一假设。
			return ledgerErrorf("操作序号 %d 同时关联两条记录（%s 与 %s）",
				ev.seq, prev.recordID, ev.recordID)
		}
		events[ev.seq] = ev
		return nil
	}

	origAdjust := make(map[string]*ledgerEvent) // 调整标识 -> 登记事件
	for _, a := range adjustmentsFor(s, customerID, month) {
		if err := addEvent(&ledgerEvent{
			seq:       a.Seq,
			kind:      evAdjust,
			recordID:  a.ID,
			dPayable:  a.Amount,
			dReceived: 0,
			reason:    a.Reason,
		}); err != nil {
			return nil, err
		}
		origAdjust[a.ID] = events[a.Seq]
	}
	origPayment := make(map[string]*ledgerEvent) // 收款标识 -> 登记事件
	for _, p := range paymentsFor(s, customerID, month) {
		alloc := p.amountFor(month)
		if err := addEvent(&ledgerEvent{
			seq:       p.Seq,
			kind:      evPayment,
			recordID:  p.ID,
			dPayable:  0,
			dReceived: alloc,
			reason:    p.Note,
		}); err != nil {
			return nil, err
		}
		origPayment[p.ID] = events[p.Seq]

		// 多月汇款的整笔撤销在同一序号取消该分配：撤销事件也按本账单
		// 分配额影响实收，其他月份的部分不进入本账单流水。
		if p.Revoked {
			rev := &ledgerEvent{
				seq:       p.RevokeSeq,
				kind:      evPaymentRevoke,
				recordID:  p.ID,
				dPayable:  0,
				dReceived: -alloc,
				reason:    p.RevokeReason,
			}
			if err := addEvent(rev); err != nil {
				return nil, err
			}
			link := &ledgerRLink{
				originSeq:  p.Seq,
				originID:   p.ID,
				reason:     p.RevokeReason,
				originKind: evPayment,
			}
			events[p.Seq].revoke = link
			rev.revoke = link
		}
	}
	for _, a := range adjustmentsFor(s, customerID, month) {
		if !a.Revoked {
			continue
		}
		rev := &ledgerEvent{
			seq:       a.RevokeSeq,
			kind:      evAdjustRevoke,
			recordID:  a.ID,
			dPayable:  -a.Amount,
			dReceived: 0,
			reason:    a.RevokeReason,
		}
		if err := addEvent(rev); err != nil {
			return nil, err
		}
		link := &ledgerRLink{
			originSeq:  a.Seq,
			originID:   a.ID,
			reason:     a.RevokeReason,
			originKind: evAdjust,
		}
		events[a.Seq].revoke = link
		rev.revoke = link
	}

	// 2) 引用失效 / 撤销先于原操作等完整性检查（在逐事件回放之外，
	//    保证即使某一步余额异常也能先报告结构问题——两者都拒绝即可）。
	for _, a := range adjustmentsFor(s, customerID, month) {
		if a.Revoked {
			if a.RevokeSeq <= a.Seq {
				return nil, ledgerErrorf("调整 %q 的撤销序号 %d 不晚于原操作序号 %d",
					a.ID, a.RevokeSeq, a.Seq)
			}
			if _, ok := events[a.RevokeSeq]; !ok {
				// 撤销事件自身就在映射里，不存在即引用失效。
				return nil, ledgerErrorf("调整 %q 的撤销序号 %d 引用失效", a.ID, a.RevokeSeq)
			}
		}
	}
	for _, p := range paymentsFor(s, customerID, month) {
		if p.Revoked {
			if p.RevokeSeq <= p.Seq {
				return nil, ledgerErrorf("收款 %q 的撤销序号 %d 不晚于原操作序号 %d",
					p.ID, p.RevokeSeq, p.Seq)
			}
			if _, ok := events[p.RevokeSeq]; !ok {
				return nil, ledgerErrorf("收款 %q 的撤销序号 %d 引用失效", p.ID, p.RevokeSeq)
			}
		}
	}

	// 3) 按序号升序逐事件回放完整流水（截止之前先核验整条流水，
	//    异常在截止之后也拒绝），每一步都校验 0 ≤ 实收 ≤ 应付 ≤ MaxInt64。
	ordered := make([]*ledgerEvent, 0, len(events))
	for _, ev := range ordered0(events) {
		ordered = append(ordered, ev)
	}
	snap := ledgerSnapshot{payable: b.TotalFee, received: 0, outstanding: b.TotalFee}
	if snap.payable < 0 {
		return nil, ledgerErrorf("账单 %s 原总金额为负（%d），流水无法核验", b.ID, snap.payable)
	}
	for i, ev := range ordered {
		next, err := applyLedgerEvent(snap, ev)
		if err != nil {
			return nil, ledgerErrorf("序号 %d（%s）之后余额不合法：%w",
				ev.seq, ledgerEventName(ev.kind, ev.recordID), err)
		}
		snap = next
		_ = i
	}

	// 4) 按 cutoff 回放历史：cutoff 处的事件计入（截止包含该序号），
	//    截止之后的撤销既不影响历史余额，也不混入流水展示。
	var shown []*ledgerEvent
	hist := ledgerSnapshot{payable: b.TotalFee, received: 0, outstanding: b.TotalFee}
	for _, ev := range ordered {
		if ev.seq > cutoff {
			break
		}
		var err error
		hist, err = applyLedgerEvent(hist, ev)
		if err != nil {
			// 已在第 3 步整体核验过，理论不可达。
			return nil, ledgerErrorf("序号 %d 回放失败：%w", ev.seq, err)
		}
		shown = append(shown, ev)
	}

	return &ledgerReport{
		bill:   b,
		cust:   cust,
		maxSeq: s.NextSeq,
		cutoff: cutoff,
		events: shown,
		final:  hist,
	}, nil
}

// ordered0 返回事件映射中按序号升序排列的事件。
func ordered0(events map[int64]*ledgerEvent) []*ledgerEvent {
	out := make([]*ledgerEvent, 0, len(events))
	for _, ev := range events {
		out = append(out, ev)
	}
	seqs := make([]int64, 0, len(events))
	bySeq := make(map[int64]*ledgerEvent, len(events))
	for _, ev := range events {
		seqs = append(seqs, ev.seq)
		bySeq[ev.seq] = ev
	}
	sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
	out = out[:0]
	for _, seq := range seqs {
		out = append(out, bySeq[seq])
	}
	return out
}

// applyLedgerEvent 把单个事件作用到余额上，全程有符号 64 位整数运算，
// 并在事件后校验 0 ≤ 实收 ≤ 应付 ≤ MaxInt64。
func applyLedgerEvent(cur ledgerSnapshot, ev *ledgerEvent) (ledgerSnapshot, error) {
	payable, err := addSigned64(cur.payable, ev.dPayable)
	if err != nil {
		return ledgerSnapshot{}, ledgerErrorf("应付运算溢出（%d %+d）", cur.payable, ev.dPayable)
	}
	received, err := addSigned64(cur.received, ev.dReceived)
	if err != nil {
		return ledgerSnapshot{}, ledgerErrorf("实收运算溢出（%d %+d）", cur.received, ev.dReceived)
	}
	if payable < 0 || payable > int64Max {
		return ledgerSnapshot{}, ledgerErrorf("应付 %d 越出 [0, %d]", payable, int64Max)
	}
	if received < 0 || received > payable {
		return ledgerSnapshot{}, ledgerErrorf("实收 %d 不满足 0 ≤ 实收 ≤ 应付（应付 %d）", received, payable)
	}
	return ledgerSnapshot{
		payable:     payable,
		received:    received,
		outstanding: payable - received,
	}, nil
}

// int64Max 在不引入 math 包循环的前提下给出有符号 64 位最大值。
const int64Max = 1<<63 - 1

// ledgerErrorf 的错误属于业务错误（退出码 1），不是命令行用法错误。
type ledgerError string

func (e ledgerError) Error() string { return string(e) }

func ledgerErrorf(format string, a ...any) error {
	return ledgerError(fmt.Sprintf(format, a...))
}

// ledgerEventName 返回“调整 xxx”/“撤销收款 yyy”之类的可读描述。
func ledgerEventName(kind ledgerEventKind, id string) string {
	switch kind {
	case evAdjust:
		return "调整 " + id
	case evAdjustRevoke:
		return "撤销调整 " + id
	case evPayment:
		return "收款 " + id
	case evPaymentRevoke:
		return "撤销收款 " + id
	default:
		return "未知事件 " + id
	}
}

// --- 命令行入口与渲染 -----------------------------------------------------

// cmdBillLedger 处理 bill ledger <客户标识> <YYYY-MM> [截止操作序号]。
// 查询只读：成功或失败都不落盘、不占用序号、不新增记录。
func cmdBillLedger(dir, customerID, month, cutoffText string) error {
	if !validMonth(month) {
		return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
	}
	s, err := loadStore(dir)
		if err != nil {
		return err
	}
	if _, ok := s.Customers[customerID]; !ok {
		return fmt.Errorf("客户标识 %q 不存在", customerID)
	}
	b, ok := s.Bills[billKey(customerID, month)]
	if !ok {
		return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
	}

	// 截止序号省略表示最新（存档全局序号上限）；0 只返回初始余额；
	// 截止包含该序号本身。
	cutoff := s.NextSeq
	if cutoffText != "" {
		v, err := parseCutoffSeq(cutoffText)
		if err != nil {
			return err
		}
		if v > s.NextSeq {
			return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d，拒绝查询", v, s.NextSeq)
		}
		cutoff = v
	}

	report, err := buildLedger(s, customerID, month, cutoff)
	if err != nil {
		return err
	}
	_ = b
	printLedger(report)
	return nil
}

// parseCutoffSeq 解析截止操作序号：只接受非负整数。
// 负数、非整数（小数/非数字）均拒绝（超过上限由调用方判断）。
func parseCutoffSeq(text string) (int64, error) {
	text = strings.TrimSpace(text)
	// strconv.ParseInt 已拒绝小数、空白内嵌、非数字；BitSize=64 限制范围。
	v, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("截止操作序号 %q 必须是非负整数（0 只返回初始余额，省略表示最新）: %w", text, err)
	}
	if v < 0 {
		return 0, fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
	}
	return v, 0
}

// printLedger 渲染对账流水报告。
func printLedger(r *ledgerReport) {
	fmt.Fprintf(stdout, "账后对账流水\n")
	fmt.Fprintf(stdout, "账单标识：%s\n", r.bill.ID)
	fmt.Fprintf(stdout, "客户：%s（%s）\n", r.cust.ID, r.cust.Name)
	fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", r.bill.Month)
	fmt.Fprintf(stdout, "原总金额：%d 分（%s）—— 账后流水起点（初始应付）\n",
		r.bill.TotalFee, moneyFen(r.bill.TotalFee))
	fmt.Fprintf(stdout, "存档全局序号上限：%d\n", r.maxSeq)
	fmt.Fprintf(stdout, "查询截止序号：%d%s\n", r.cutoff, cutoffNote(r))
	if len(r.events) == 0 {
		fmt.Fprintln(stdout, "流水：空（截止以内没有调整、收款或其撤销事件）")
	} else {
		fmt.Fprintln(stdout, "流水（按成功操作序号升序，截止包含该序号）：")
		for i, ev := range r.events {
			fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(r, ev))
		}
	}
	fmt.Fprintln(stdout, "截止时余额：")
	fmt.Fprintf(stdout, "  应付：%d 分（%s）\n", r.final.payable, moneyFen(r.final.payable))
	fmt.Fprintf(stdout, "  实收：%d 分（%s）\n", r.final.received, moneyFen(r.final.received))
	fmt.Fprintf(stdout, "  未收余额：%d 分（%s）\n", r.final.outstanding, moneyFen(r.final.outstanding))
}

func cutoffNote(r *ledgerReport) string {
	if r.cutoff == 0 {
		return "（0：只返回初始余额）"
	}
	if r.cutoff == r.maxSeq {
		return "（最新）"
	}
	return ""
}

// formatLedgerEvent 渲染单个事件：序号、类型、原记录标识、金额影响、
// 原因/备注、撤销关联，以及事件后的应付/实收/未收余额。
// 收款事件同时给出汇款总额与本账单分配。
func formatLedgerEvent(r *ledgerReport, ev *ledgerEvent) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "序号=%d 类型=%s 原记录=%s", ev.seq, ledgerKindName(ev.kind), ev.recordID)
	switch ev.kind {
	case evAdjust:
		fmt.Fprintf(&sb, " 金额影响：应付 %+d 分", ev.dPayable)
	case evAdjustRevoke:
		fmt.Fprintf(&sb, " 金额影响：应付 %+d 分（抵消调整 %s）", ev.dPayable, ev.recordID)
	case evPayment:
		// 汇款总额需要从存档取原始 payment 记录。
		if p := findPayment(r, ev.recordID); p != nil {
			fmt.Fprintf(&sb, " 汇款总额=%d 分（%s） 本账单分配=%d 分（%s） 金额影响：实收 +%d 分",
				p.Total, moneyFen(p.Total), ev.dReceived, moneyFen(ev.dReceived), ev.dReceived)
		} else {
			fmt.Fprintf(&sb, " 本账单分配=%d 分 金额影响：实收 +%d 分", ev.dReceived, ev.dReceived)
		}
	case evPaymentRevoke:
		if p := findPayment(r, ev.recordID); p != nil {
			fmt.Fprintf(&sb, " 汇款总额=%d 分（%s） 本账单分配=%d 分（%s） 金额影响：实收 %+d 分（整笔撤销在同一序号取消该分配）",
				p.Total, moneyFen(p.Total), -ev.dReceived, moneyFen(-ev.dReceived), ev.dReceived)
		} else {
			fmt.Fprintf(&sb, " 金额影响：实收 %+d 分（整笔撤销在同一序号取消该分配）", ev.dReceived)
		}
	}
	if ev.reason != "" {
		fmt.Fprintf(&sb, " %s：%s", ledgerReasonLabel(ev.kind), ev.reason)
	}
	if ev.revoke != nil {
		switch ev.kind {
		case evAdjust, evPayment:
			// 原操作事件：仅当撤销序号也在截止以内时才提示“已在序号 N 撤销”；
			// 截止之后的撤销不得影响历史展示的事件关联口径——但撤销关联字段
			// 仍需如实呈现存档事实，因此标注其发生序号，便于核对。
			fmt.Fprintf(&sb, " 撤销关联：%s（撤销序号 %d，原因：%s）",
				ledgerRevokeText(ev), ev.revoke.originSeq == 0 && false, ev.revoke.reason)
		case evAdjustRevoke, evPaymentRevoke:
			fmt.Fprintf(&sb, " 撤销关联：抵消序号 %d 的%s（%s）",
				ev.revoke.originSeq, ledgerKindName(ev.revoke.originKind), ev.revoke.originID)
		}
	}
	// 事件后余额：重新按前缀回放取得（事件切片按序，增量计算见调用方缓存）。
	snap := r.snapshotAt(ev.seq)
	fmt.Fprintf(&sb, " | 事件后：应付=%d 实收=%d 未收=%d",
		snap.payable, snap.received, snap.outstanding)
	return sb.String()
}

// ledgerRevokeText 用于原操作事件上的撤销关联说明。
func ledgerRevokeText(ev *ledgerEvent) string {
	if ev.kind == evAdjust {
		return fmt.Sprintf("已于后续序号撤销（调整 %s）", ev.recordID)
	}
	return fmt.Sprintf("已于后续序号撤销（收款 %s）", ev.recordID)
}

func ledgerKindName(k ledgerEventKind) string {
	switch k {
	case evAdjust:
		return "调整"
	case evAdjustRevoke:
		return "调整撤销"
	case evPayment:
		return "收款"
	case evPaymentRevoke:
		return "收款撤销"
	default:
		return "未知"
	}
}

func ledgerReasonLabel(k ledgerEventKind) string {
	switch k {
	case evAdjust:
		return "原因"
	case evAdjustRevoke:
		return "撤销原因"
	case evPayment:
		return "备注"
	case evPaymentRevoke:
		return "撤销原因"
	default:
		return "说明"
	}
}

// findPayment 按标识在报告需要时回看存档收款记录（汇款总额）。
// 报告本身不持有 state，因此在构建报告时把所需总额带上更干净——
// 这里通过 events 无法拿到总额，改为在 report 中保存映射。
var _ = sort.Slice

// paymentTotals 由 buildLedger 填充进报告：记录标识 -> 汇款总额。

toolUseResult.content:
package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// 账后对账流水（bill ledger）：
//
// 把一张已结算账单的调整/调整撤销、收款/收款撤销合并为一条按全局操作序号
// （调整、收款及其撤销共用同一个已保存的全局序号池）升序排列的流水，
// 只回看账后变化：初始应付 = 账单原总金额，初始实收 = 0，
// 不推断查询时该账单是否仍处于某个结算状态。
//
// 关键约束：
//   - 调整只改变应付；收款（在本账单的分配）只改变实收；
//   - 撤销在其发生序号抵消对应原操作：已撤销记录在撤销之前仍计入，
//     不能按当前撤销状态提前扣除或删除原事件；
//   - 每个事件后都必须满足 0 ≤ 实收 ≤ 应付 ≤ MaxInt64；
//   - 查询前核验目标账单的完整流水，即使异常事件落在截止序号之后也拒绝；
//   - 查询只读：绝不调用 save，不占用序号、不新增记录。

// ledgerEventKind 描述事件类型。
type ledgerEventKind int

const (
	evAdjust        ledgerEventKind = iota // 调整登记
	evAdjustRevoke                         // 调整撤销
	evPayment                              // 收款登记
	evPaymentRevoke                        // 收款撤销
)

// ledgerEvent 是合并后流水中的一个条目，对应全局序号上的一次成功操作
// （或幂等重放本来就不占序号——见 state.validate 已拒绝重复序号）。
type ledgerEvent struct {
	seq      int64
	kind     ledgerEventKind
	recordID string       // 原记录标识（调整/收款自身的标识）
	dPayable int64        // 对应付的影响（调整 ±amount；其他为 0）
	dReceived int64       // 对实收的影响：收款 +本账单分配；撤销为 -原影响
	reason   string       // 登记事件的原因/备注
	revoke   *ledgerRLink // 撤销事件：关联原操作；原操作事件：若最终被撤销则指向链接
}

// ledgerRLink 描述事件之间的撤销关联。
type ledgerRLink struct {
	originSeq int64  // 被抵消的原操作序号
	originID  string // 被抵消的原记录标识
	reason    string // 撤销原因
	originKind ledgerEventKind
}

// ledgerSnapshot 是某个事件之后该账单的三项余额。
type ledgerSnapshot struct {
	payable    int64
	received   int64
	outstanding int64
}

// ledgerReport 包含回放结果与展示所需的全部信息。
class-unused
type ledgerReport struct {
	bill       *bill
	cust       *customer
	maxSeq     int64 // 存档全局序号上限（state.NextSeq）
	cutoff     int64 // 查询采用的截止序号（省略时等于 maxSeq；0 只看初始余额）
	events     []*ledgerEvent
	final      ledgerSnapshot
}

// buildLedger 收集目标账单的全部调整/收款（含撤销），合并为按序号升序的
// 完整流水，并逐事件重放核验不变量（覆盖到存档上限，超出本账单事件的
// 空档合法）；随后按 cutoff 回放得到历史余额。
//
// 这是一个只读操作：即使 buildLedger 失败也不会修改 *state*。
func buildLedger(s *state, customerID, month string, cutoff int64) (*ledgerReport, error) {
	b, ok := s.Bills[billKey(customerID, month)]
	if !ok {
		return nil, fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
	}
	cust := s.Customers[customerID] // validate 已保证存在

	// 1) 收集本账单相关的全部事件，建立 序号 -> 事件 映射，用于撤销关联与
	//    引用、重复、时序完整性检查。
	events := make(map[int64]*ledgerEvent)
	addEvent := func(ev *ledgerEvent) error {
		if prev, dup := events[ev.seq]; _ = dup; dup {
			// 正常不会发生（loadStore.validate 已拒绝全局序号重复），
			// 但流水核验不依赖 validate 已跑过这一假设。
			return ledgerErrorf("操作序号 %d 同时关联两条记录（%s 与 %s）",
				ev.seq, prev.recordID, ev.recordID)
		}
		events[ev.seq] = ev
		return nil
	}

	origAdjust := make(map[string]*ledgerEvent) // 调整标识 -> 登记事件
	for _, a := range adjustmentsFor(s, customerID, month) {
		if err := addEvent(&ledgerEvent{
			seq:       a.Seq,
			kind:      evAdjust,
			recordID:  a.ID,
			dPayable:  a.Amount,
			dReceived: 0,
			reason:    a.Reason,
		}); err != nil {
			return nil, err
		}
		origAdjust[a.ID] = events[a.Seq]
	}
	origPayment := make(map[string]*ledgerEvent) // 收款标识 -> 登记事件
	for _, p := range paymentsFor(s, customerID, month) {
		alloc := p.amountFor(month)
		if err := addEvent(&ledgerEvent{
			seq:       p.Seq,
			kind:      evPayment,
			recordID:  p.ID,
			dPayable:  0,
			dReceived: alloc,
			reason:    p.Note,
		}); err != nil {
			return nil, err
		}
		origPayment[p.ID] = events[p.Seq]

		// 多月汇款的整笔撤销在同一序号取消该分配：撤销事件也按本账单
		// 分配额影响实收，其他月份的部分不进入本账单流水。
		if p.Revoked {
			rev := &ledgerEvent{
				seq:       p.RevokeSeq,
				kind:      evPaymentRevoke,
				recordID:  p.ID,
				dPayable:  0,
				dReceived: -alloc,
				reason:    p.RevokeReason,
			}
			if err := addEvent(rev); err != nil {
				return nil, err
			}
			link := &ledgerRLink{
				originSeq:  p.Seq,
				originID:   p.ID,
				reason:     p.RevokeReason,
				originKind: evPayment,
			}
			events[p.Seq].revoke = link
			rev.revoke = link
		}
	}
	for _, a := range adjustmentsFor(s, customerID, month) {
		if !a.Revoked {
			continue
		}
		rev := &ledgerEvent{
			seq:       a.RevokeSeq,
			kind:      evAdjustRevoke,
			recordID:  a.ID,
			dPayable:  -a.Amount,
			dReceived: 0,
			reason:    a.RevokeReason,
		}
		if err := addEvent(rev); err != nil {
			return nil, err
		}
		link := &ledgerRLink{
			originSeq:  a.Seq,
			originID:   a.ID,
			reason:     a.RevokeReason,
			originKind: evAdjust,
		}
		events[a.Seq].revoke = link
		rev.revoke = link
	}

	// 2) 引用失效 / 撤销先于原操作等完整性检查（在逐事件回放之外，
	//    保证即使某一步余额异常也能先报告结构问题——两者都拒绝即可）。
	for _, a := range adjustmentsFor(s, customerID, month) {
		if a.Revoked {
			if a.RevokeSeq <= a.Seq {
				return nil, ledgerErrorf("调整 %q 的撤销序号 %d 不晚于原操作序号 %d",
					a.ID, a.RevokeSeq, a.Seq)
			}
			if _, ok := events[a.RevokeSeq]; !ok {
				// 撤销事件自身就在映射里，不存在即引用失效。
				return nil, ledgerErrorf("调整 %q 的撤销序号 %d 引用失效", a.ID, a.RevokeSeq)
			}
		}
	}
	for _, p := range paymentsFor(s, customerID, month) {
		if p.Revoked {
			if p.RevokeSeq <= p.Seq {
				return nil, ledgerErrorf("收款 %q 的撤销序号 %d 不晚于原操作序号 %d",
					p.ID, p.RevokeSeq, p.Seq)
			}
			if _, ok := events[p.RevokeSeq]; !ok {
				return nil, ledgerErrorf("收款 %q 的撤销序号 %d 引用失效", p.ID, p.RevokeSeq)
			}
		}
	}

	// 3) 按序号升序逐事件回放完整流水（截止之前先核验整条流水，
	//    异常在截止之后也拒绝），每一步都校验 0 ≤ 实收 ≤ 应付 ≤ MaxInt64。
	ordered := make([]*ledgerEvent, 0, len(events))
	for _, ev := range ordered0(events) {
		ordered = append(ordered, ev)
	}
	snap := ledgerSnapshot{payable: b.TotalFee, received: 0, outstanding: b.TotalFee}
	if snap.payable < 0 {
		return nil, ledgerErrorf("账单 %s 原总金额为负（%d），流水无法核验", b.ID, snap.payable)
	}
	for i, ev := range ordered {
		next, err := applyLedgerEvent(snap, ev)
		if err != nil {
			return nil, ledgerErrorf("序号 %d（%s）之后余额不合法：%w",
				ev.seq, ledgerEventName(ev.kind, ev.recordID), err)
		}
		snap = next
		_ = i
	}

	// 4) 按 cutoff 回放历史：cutoff 处的事件计入（截止包含该序号），
	//    截止之后的撤销既不影响历史余额，也不混入流水展示。
	var shown []*ledgerEvent
	hist := ledgerSnapshot{payable: b.TotalFee, received: 0, outstanding: b.TotalFee}
	for _, ev := range ordered {
		if ev.seq > cutoff {
			break
		}
		var err error
		hist, err = applyLedgerEvent(hist, ev)
		if err != nil {
			// 已在第 3 步整体核验过，理论不可达。
			return nil, ledgerErrorf("序号 %d 回放失败：%w", ev.seq, err)
		}
		shown = append(shown, ev)
	}

	return &ledgerReport{
		bill:   b,
		cust:   cust,
		maxSeq: s.NextSeq,
		cutoff: cutoff,
		events: shown,
		final:  hist,
	}, nil
}

// ordered0 返回事件映射中按序号升序排列的事件。
func ordered0(events map[int64]*ledgerEvent) []*ledgerEvent {
	out := make([]*ledgerEvent, 0, len(events))
	for _, ev := range events {
		out = append(out, ev)
	}
	seqs := make([]int64, 0, len(events))
	bySeq := make(map[int64]*ledgerEvent, len(events))
	for _, ev := range events {
		seqs = append(seqs, ev.seq)
		bySeq[ev.seq] = ev
	}
	sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
	out = out[:0]
	for _, seq := range seqs {
		out = append(out, bySeq[seq])
	}
	return out
}

// applyLedgerEvent 把单个事件作用到余额上，全程有符号 64 位整数运算，
// 并在事件后校验 0 ≤ 实收 ≤ 应付 ≤ MaxInt64。
func applyLedgerEvent(cur ledgerSnapshot, ev *ledgerEvent) (ledgerSnapshot, error) {
	payable, err := addSigned64(cur.payable, ev.dPayable)
	if err != nil {
		return ledgerSnapshot{}, ledgerErrorf("应付运算溢出（%d %+d）", cur.payable, ev.dPayable)
	}
	received, err := addSigned64(cur.received, ev.dReceived)
	if err != nil {
		return ledgerSnapshot{}, ledgerErrorf("实收运算溢出（%d %+d）", cur.received, ev.dReceived)
	}
	if payable < 0 || payable > int64Max {
		return ledgerSnapshot{}, ledgerErrorf("应付 %d 越出 [0, %d]", payable, int64Max)
	}
	if received < 0 || received > payable {
		return ledgerSnapshot{}, ledgerErrorf("实收 %d 不满足 0 ≤ 实收 ≤ 应付（应付 %d）", received, payable)
	}
	return ledgerSnapshot{
		payable:     payable,
		received:    received,
		outstanding: payable - received,
	}, nil
}

// int64Max 在不引入 math 包循环的前提下给出有符号 64 位最大值。
const int64Max = 1<<63 - 1

// ledgerErrorf 的错误属于业务错误（退出码 1），不是命令行用法错误。
type ledgerError string

func (e ledgerError) Error() string { return string(e) }

func ledgerErrorf(format string, a ...any) error {
	return ledgerError(fmt.Sprintf(format, a...))
}

// ledgerEventName 返回“调整 xxx”/“撤销收款 yyy”之类的可读描述。
func ledgerEventName(kind ledgerEventKind, id string) string {
	switch kind {
	case evAdjust:
		return "调整 " + id
	case evAdjustRevoke:
		return "撤销调整 " + id
	case evPayment:
		return "收款 " + id
	case evPaymentRevoke:
		return "撤销收款 " + id
	default:
		return "未知事件 " + id
	}
}

// --- 命令行入口与渲染 -----------------------------------------------------

// cmdBillLedger 处理 bill ledger <客户标识> <YYYY-MM> [截止操作序号]。
// 查询只读：成功或失败都不落盘、不占用序号、不新增记录。
func cmdBillLedger(dir, customerID, month, cutoffText string) error {
	if !validMonth(month) {
		return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
	}
	s, err := loadStore(dir)
		if err != nil {
		return err
	}
	if _, ok := s.Customers[customerID]; !ok {
		return fmt.Errorf("客户标识 %q 不存在", customerID)
	}
	b, ok := s.Bills[billKey(customerID, month)]
	if !ok {
		return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
	}

	// 截止序号省略表示最新（存档全局序号上限）；0 只返回初始余额；
	// 截止包含该序号本身。
	cutoff := s.NextSeq
	if cutoffText != "" {
		v, err := parseCutoffSeq(cutoffText)
		if err != nil {
			return err
		}
		if v > s.NextSeq {
			return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d，拒绝查询", v, s.NextSeq)
		}
		cutoff = v
	}

	report, err := buildLedger(s, customerID, month, cutoff)
	if err != nil {
		return err
	}
	_ = b
	printLedger(report)
	return nil
}

// parseCutoffSeq 解析截止操作序号：只接受非负整数。
// 负数、非整数（小数/非数字）均拒绝（超过上限由调用方判断）。
func parseCutoffSeq(text string) (int64, error) {
	text = strings.TrimSpace(text)
	// strconv.ParseInt 已拒绝小数、空白内嵌、非数字；BitSize=64 限制范围。
	v, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("截止操作序号 %q 必须是非负整数（0 只返回初始余额，省略表示最新）: %w", text, err)
	}
	if v < 0 {
		return 0, fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
	}
	return v, 0
}

// printLedger 渲染对账流水报告。
func printLedger(r *ledgerReport) {
	fmt.Fprintf(stdout, "账后对账流水\n")
	fmt.Fprintf(stdout, "账单标识：%s\n", r.bill.ID)
	fmt.Fprintf(stdout, "客户：%s（%s）\n", r.cust.ID, r.cust.Name)
	fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", r.bill.Month)
	fmt.Fprintf(stdout, "原总金额：%d 分（%s）—— 账后流水起点（初始应付）\n",
		r.bill.TotalFee, moneyFen(r.bill.TotalFee))
	fmt.Fprintf(stdout, "存档全局序号上限：%d\n", r.maxSeq)
	fmt.Fprintf(stdout, "查询截止序号：%d%s\n", r.cutoff, cutoffNote(r))
	if len(r.events) == 0 {
		fmt.Fprintln(stdout, "流水：空（截止以内没有调整、收款或其撤销事件）")
	} else {
		fmt.Fprintln(stdout, "流水（按成功操作序号升序，截止包含该序号）：")
		for i, ev := range r.events {
			fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(r, ev))
		}
	}
	fmt.Fprintln(stdout, "截止时余额：")
	fmt.Fprintf(stdout, "  应付：%d 分（%s）\n", r.final.payable, moneyFen(r.final.payable))
	fmt.Fprintf(stdout, "  实收：%d 分（%s）\n", r.final.received, moneyFen(r.final.received))
	fmt.Fprintf(stdout, "  未收余额：%d 分（%s）\n", r.final.outstanding, moneyFen(r.final.outstanding))
}

func cutoffNote(r *ledgerReport) string {
	if r.cutoff == 0 {
		return "（0：只返回初始余额）"
	}
	if r.cutoff == r.maxSeq {
		return "（最新）"
	}
	return ""
}

// formatLedgerEvent 渲染单个事件：序号、类型、原记录标识、金额影响、
// 原因/备注、撤销关联，以及事件后的应付/实收/未收余额。
// 收款事件同时给出汇款总额与本账单分配。
func formatLedgerEvent(r *ledgerReport, ev *ledgerEvent) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "序号=%d 类型=%s 原记录=%s", ev.seq, ledgerKindName(ev.kind), ev.recordID)
	switch ev.kind {
	case evAdjust:
		fmt.Fprintf(&sb, " 金额影响：应付 %+d 分", ev.dPayable)
	case evAdjustRevoke:
		fmt.Fprintf(&sb, " 金额影响：应付 %+d 分（抵消调整 %s）", ev.dPayable, ev.recordID)
	case evPayment:
		// 汇款总额需要从存档取原始 payment 记录。
		if p := findPayment(r, ev.recordID); p != nil {
			fmt.Fprintf(&sb, " 汇款总额=%d 分（%s） 本账单分配=%d 分（%s） 金额影响：实收 +%d 分",
				p.Total, moneyFen(p.Total), ev.dReceived, moneyFen(ev.dReceived), ev.dReceived)
		} else {
			fmt.Fprintf(&sb, " 本账单分配=%d 分 金额影响：实收 +%d 分", ev.dReceived, ev.dReceived)
		}
	case evPaymentRevoke:
		if p := findPayment(r, ev.recordID); p != nil {
			fmt.Fprintf(&sb, " 汇款总额=%d 分（%s） 本账单分配=%d 分（%s） 金额影响：实收 %+d 分（整笔撤销在同一序号取消该分配）",
				p.Total, moneyFen(p.Total), -ev.dReceived, moneyFen(-ev.dReceived), ev.dReceived)
		} else {
			fmt.Fprintf(&sb, " 金额影响：实收 %+d 分（整笔撤销在同一序号取消该分配）", ev.dReceived)
		}
	}
	if ev.reason != "" {
		fmt.Fprintf(&sb, " %s：%s", ledgerReasonLabel(ev.kind), ev.reason)
	}
	if ev.revoke != nil {
		switch ev.kind {
		case evAdjust, evPayment:
			// 原操作事件：仅当撤销序号也在截止以内时才提示“已在序号 N 撤销”；
			// 截止之后的撤销不得影响历史展示的事件关联口径——但撤销关联字段
			// 仍需如实呈现存档事实，因此标注其发生序号，便于核对。
			fmt.Fprintf(&sb, " 撤销关联：%s（撤销序号 %d，原因：%s）",
				ledgerRevokeText(ev), ev.revoke.originSeq == 0 && false, ev.revoke.reason)
		case evAdjustRevoke, evPaymentRevoke:
			fmt.Fprintf(&sb, " 撤销关联：抵消序号 %d 的%s（%s）",
				ev.revoke.originSeq, ledgerKindName(ev.revoke.originKind), ev.revoke.originID)
		}
	}
	// 事件后余额：重新按前缀回放取得（事件切片按序，增量计算见调用方缓存）。
	snap := r.snapshotAt(ev.seq)
	fmt.Fprintf(&sb, " | 事件后：应付=%d 实收=%d 未收=%d",
		snap.payable, snap.received, snap.outstanding)
	return sb.String()
}

// ledgerRevokeText 用于原操作事件上的撤销关联说明。
func ledgerRevokeText(ev *ledgerEvent) string {
	if ev.kind == evAdjust {
		return fmt.Sprintf("已于后续序号撤销（调整 %s）", ev.recordID)
	}
	return fmt.Sprintf("已于后续序号撤销（收款 %s）", ev.recordID)
}

func ledgerKindName(k ledgerEventKind) string {
	switch k {
	case evAdjust:
		return "调整"
	case evAdjustRevoke:
		return "调整撤销"
	case evPayment:
		return "收款"
	case evPaymentRevoke:
		return "收款撤销"
	default:
		return "未知"
	}
}

func ledgerReasonLabel(k ledgerEventKind) string {
	switch k {
	case evAdjust:
		return "原因"
	case evAdjustRevoke:
		return "撤销原因"
	case evPayment:
		return "备注"
	case evPaymentRevoke:
		return "撤销原因"
	default:
		return "说明"
	}
}

// findPayment 按标识在报告需要时回看存档收款记录（汇款总额）。
// 报告本身不持有 state，因此在构建报告时把所需总额带上更干净——
// 这里通过 events 无法拿到总额，改为在 report 中保存映射。
var _ = sort.Slice

// paymentTotals 由 buildLedger 填充进报告：记录标识 -> 汇款总额。

input.content:
package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// 账后对账流水（bill ledger）：
//
// 把一张已结算账单的调整/调整撤销、收款/收款撤销合并为一条按全局操作序号
// （调整、收款及其撤销共用同一个已保存的全局序号池）升序排列的流水，
// 只回看账后变化：初始应付 = 账单原总金额，初始实收 = 0，
// 不推断查询时该账单是否已结算或某笔记录当前是否已撤销。
//
// 关键规则：
//   - 调整只改变应付；收款只按其在本账单的分配改变实收；
//   - 撤销在其发生序号抵消对应原操作：已撤销记录在撤销之前仍须计入，
//     不能按当前撤销状态提前扣除或删除原事件；
//   - 每个事件后都必须满足 0 ≤ 实收 ≤ 应付 ≤ MaxInt64，不只检查最终余额；
//   - 查询前核验目标账单的完整流水，异常即使发生在截止序号之后也拒绝；
//   - 查询只读：绝不落盘、不占用序号、不新增记录。

// ledgerEventKind 描述流水事件类型。
type ledgerEventKind int

const (
	evAdjust ledgerEventKind = iota // 调整登记
	evAdjustRevoke                  // 调整撤销
	evPayment                       // 收款登记
	evPaymentRevoke                 // 收款撤销
)

// ledgerEvent 是合并后流水中的一个条目。
type ledgerEvent struct {
	seq       int64
	kind      ledgerEventKind
	recordID  string // 原记录标识（调整/收款自身的标识）
	dPayable  int64  // 对应付的影响：调整 ±amount；其余为 0
	dReceived int64  // 对实收的影响：收款 +本账单分配；撤销为 -原影响
	reason    string // 登记原因/备注，或撤销原因
	payTotal  int64  // 收款类事件的汇款总额；其余为 0

	revokeSeq  int64           // 原操作事件：撤销发生序号（0 表示存档中未撤销）
	originSeq  int64           // 撤销事件：被抵消原操作的序号
	originKind ledgerEventKind // 撤销事件：被抵消原操作的类型

	post ledgerSnapshot // 事件后余额（cutoff 回放时写入）
}

// ledgerSnapshot 是某个时点该账单的三项余额。
type ledgerSnapshot struct {
	payable     int64
	received    int64
	outstanding int64
}

// ledgerReport 是一次流水查询的结果。
type ledgerReport struct {
	bill   *bill
	cust   *customer
	maxSeq int64 // 存档全局序号上限（state.NextSeq）
	cutoff int64 // 查询采用的截止序号（省略等于 maxSeq；0 只看初始余额）
	events []*ledgerEvent
	final  ledgerSnapshot
}

// buildLedger 构建并核验目标账单的完整账后流水，再按 cutoff 回放。
func buildLedger(s *state, customerID, month string, cutoff int64) (*ledgerReport, error) {
	b, ok := s.Bills[billKey(customerID, month)]
	if !ok {
		return nil, fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
	}
	cust := s.Customers[customerID] // loadStore 已校验存在

	adjs := adjustmentsFor(s, customerID, month)
	pays := paymentsFor(s, customerID, month)

	// 1) 全局序号占用核验：序号重复一律拒绝（即使 loadStore.validate 已查过，
	//    流水核验不依赖这一前提）。
	if err := checkGlobalSeqOwners(s); err != nil {
		return nil, err
	}

	// 2) 收集本账单的全部事件到 序号 -> 事件 映射。其他客户/月份造成的
	//    序号空档不进入映射，回放时自然跳过，属合法。
	events := make(map[int64]*ledgerEvent)
	addEvent := func(ev *ledgerEvent) error {
		if ev.seq < 1 || ev.seq > s.NextSeq {
			return fmt.Errorf("操作序号 %d（%s）越出存档序号范围 [1, %d]，流水引用失效",
				ev.seq, ledgerEventName(ev.kind, ev.recordID), s.NextSeq)
		}
		if prev, dup := events[ev.seq]; dup {
			return fmt.Errorf("操作序号 %d 重复：%s 与 %s", ev.seq,
				ledgerEventName(prev.kind, prev.recordID), ledgerEventName(ev.kind, ev.recordID))
		}
		events[ev.seq] = ev
		return nil
	}

	for _, a := range adjs {
		if err := addEvent(&ledgerEvent{
			seq:       a.Seq,
			kind:      evAdjust,
			recordID:  a.ID,
			dPayable:  a.Amount,
			reason:    a.Reason,
			revokeSeq: a.revokeSeqOrZero(),
		}); err != nil {
			return nil, err
		}
	}
	for _, a := range adjs {
		if !a.Revoked {
			continue
		}
		// 撤销先于原操作（或同序号）拒绝。
		if a.RevokeSeq <= a.Seq {
			return nil, fmt.Errorf("调整 %q 的撤销序号 %d 不晚于原操作序号 %d，撤销引用失效",
				a.ID, a.RevokeSeq, a.Seq)
		}
		neg, err := neg64(a.Amount)
		if err != nil {
			return nil, fmt.Errorf("调整 %q 金额 %d 取反超出有符号 64 位整数范围，流水无法核验", a.ID, a.Amount)
		}
		if err := addEvent(&ledgerEvent{
			seq:        a.RevokeSeq,
			kind:       evAdjustRevoke,
			recordID:   a.ID,
			dPayable:   neg,
			reason:     a.RevokeReason,
			originSeq:  a.Seq,
			originKind: evAdjust,
		}); err != nil {
			return nil, err
		}
	}
	for _, p := range pays {
		alloc := p.amountFor(month)
		if err := addEvent(&ledgerEvent{
			seq:       p.Seq,
			kind:      evPayment,
			recordID:  p.ID,
			dReceived: alloc,
			reason:    p.Note,
			payTotal:  p.Total,
			revokeSeq: p.revokeSeqOrZero(),
		}); err != nil {
			return nil, err
		}
	}
	for _, p := range pays {
		if !p.Revoked {
			continue
		}
		if p.RevokeSeq <= p.Seq {
			return nil, fmt.Errorf("收款 %q 的撤销序号 %d 不晚于原操作序号 %d，撤销引用失效",
				p.ID, p.RevokeSeq, p.Seq)
		}
		alloc := p.amountFor(month)
		if err := addEvent(&ledgerEvent{
			seq:        p.RevokeSeq,
			kind:       evPaymentRevoke,
			recordID:   p.ID,
			dReceived:  -alloc, // 整笔撤销在同一序号取消该账单分配
			reason:     p.RevokeReason,
			payTotal:   p.Total,
			originSeq:  p.Seq,
			originKind: evPayment,
		}); err != nil {
			return nil, err
		}
	}

	// 3) 撤销引用的原操作必须能在本账单流水中找到（引用失效拒绝）。
	for _, a := range adjs {
		if a.Revoked {
			if _, ok := events[a.Seq]; !ok {
				return nil, fmt.Errorf("调整 %q 的撤销找不到原操作（序号 %d），引用失效", a.ID, a.Seq)
			}
		}
	}
	for _, p := range pays {
		if p.Revoked {
			if _, ok := events[p.Seq]; !ok {
				return nil, fmt.Errorf("收款 %q 的撤销找不到原操作（序号 %d），引用失效", p.ID, p.Seq)
			}
		}
	}

	ordered := sortLedgerEvents(events)

	// 4) 先回放“完整流水”逐事件核验不变量：异常即使在 cutoff 之后也拒绝。
	//    累计补收或收款发生额本身可能超过 MaxInt64，只要每一步余额合法即通过。
	snap := ledgerSnapshot{payable: b.TotalFee, received: 0, outstanding: b.TotalFee}
	if snap.payable < 0 {
		return nil, fmt.Errorf("账单 %s 原总金额为负（%d），流水无法核验", b.ID, snap.payable)
	}
	for _, ev := range ordered {
		next, err := applyLedgerEvent(snap, ev)
		if err != nil {
			return nil, fmt.Errorf("完整流水核验失败：序号 %d（%s）之后余额不合法：%w",
				ev.seq, ledgerEventName(ev.kind, ev.recordID), err)
		}
		snap = next
	}

	// 5) 按 cutoff 回放历史：截止包含该序号；截止之后的事件既不影响历史
	//    余额，也不混入流水。
	shown := make([]*ledgerEvent, 0, len(ordered))
	hist := ledgerSnapshot{payable: b.TotalFee, received: 0, outstanding: b.TotalFee}
	for _, ev := range ordered {
		if ev.seq > cutoff {
			break
		}
		next, err := applyLedgerEvent(hist, ev)
		if err != nil {
			return nil, fmt.Errorf("序号 %d 回放失败：%w", ev.seq, err) // 理论不可达：第 4 步已核验
		}
		hist = next
		ev.post = hist
		shown = append(shown, ev)
	}

	return &ledgerReport{
		bill:   b,
		cust:   cust,
		maxSeq: s.NextSeq,
		cutoff: cutoff,
		events: shown,
		final:  hist,
	}, nil
}

// revokeSeqOrZero 返回记录的撤销序号；未撤销时为 0。
func (a *adjustment) revokeSeqOrZero() int64 {
	if a.Revoked {
		return a.RevokeSeq
	}
	return 0
}

func (p *payment) revokeSeqOrZero() int64 {
	if p.Revoked {
		return p.RevokeSeq
	}
	return 0
}

// checkGlobalSeqOwners 核验全库调整/收款及其撤销的序号互不重复、均落在
// [1, NextSeq] 内。loadStore.validate 已做同等检查，这里再独立核验一遍，
// 使流水查询不依赖“载入时一定校验过”的假设。
func checkGlobalSeqOwners(s *state) error {
	owner := make(map[int64]string)
	claim := func(seq int64, who string) error {
		if seq < 1 || seq > s.NextSeq {
			return fmt.Errorf("%s 的操作序号 %d 越出存档序号范围 [1, %d]，引用失效", who, seq, s.NextSeq)
		}
		if prev, dup := owner[seq]; dup {
			return fmt.Errorf("操作序号 %d 重复：%s 与 %s", seq, prev, who)
		}
		owner[seq] = who
		return nil
	}
	// 遍历顺序不确定，但只用于发现重复/越界，与顺序无关。
	for id, a := range s.Adjustments {
		if err := claim(a.Seq, "调整 "+id); err != nil {
			return err
		}
		if a.Revoked {
			if err := claim(a.RevokeSeq, "撤销调整 "+id); err != nil {
				return err
			}
		}
	}
	for id, p := range s.Payments {
		if err := claim(p.Seq, "收款 "+id); err != nil {
			return err
		}
		if p.Revoked {
			if err := claim(p.RevokeSeq, "撤销收款 "+id); err != nil {
				return err
			}
		}
	}
	return nil
}

// sortLedgerEvents 按序号升序返回事件。
func sortLedgerEvents(events map[int64]*ledgerEvent) []*ledgerEvent {
	out := make([]*ledgerEvent, 0, len(events))
	for _, ev := range events {
		out = append(out, ev)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].seq < out[j].seq })
	return out
}

// applyLedgerEvent 把单个事件作用到余额上，全程有符号 64 位整数运算，
// 事件后校验 0 ≤ 实收 ≤ 应付 ≤ MaxInt64。
func applyLedgerEvent(cur ledgerSnapshot, ev *ledgerEvent) (ledgerSnapshot, error) {
	payable, err := addSigned64(cur.payable, ev.dPayable)
	if err != nil {
		return ledgerSnapshot{}, fmt.Errorf("应付运算溢出（%d %+d）", cur.payable, ev.dPayable)
	}
	received, err := addSigned64(cur.received, ev.dReceived)
	if err != nil {
		return ledgerSnapshot{}, fmt.Errorf("实收运算溢出（%d %+d）", cur.received, ev.dReceived)
	}
	if payable < 0 || payable > int64Max {
		return ledgerSnapshot{}, fmt.Errorf("应付 %d 越出 [0, %d]", payable, int64Max)
	}
	if received < 0 {
		return ledgerSnapshot{}, fmt.Errorf("实收 %d 小于 0（应付 %d）", received, payable)
	}
	if received > payable {
		return ledgerSnapshot{}, fmt.Errorf("实收 %d 超过应付 %d", received, payable)
	}
	return ledgerSnapshot{
		payable:     payable,
		received:    received,
		outstanding: payable - received,
	}, nil
}

// int64Max 是有符号 64 位整数最大值。
const int64Max = 1<<63 - 1

// ledgerEventName 返回“调整 xxx”/“撤销收款 yyy”之类的可读描述。
func ledgerEventName(kind ledgerEventKind, id string) string {
	switch kind {
	case evAdjust:
		return "调整 " + id
	case evAdjustRevoke:
		return "撤销调整 " + id
	case evPayment:
		return "收款 " + id
	case evPaymentRevoke:
		return "撤销收款 " + id
	default:
		return "未知事件 " + id
	}
}

// --- 命令行入口与渲染 -----------------------------------------------------

// cmdBillLedger 处理 bill ledger <客户标识> <YYYY-MM> [截止操作序号]。
// 查询只读：成功或失败都不落盘、不占用序号、不新增记录。
func cmdBillLedger(dir, customerID, month, cutoffText string) error {
	if !validMonth(month) {
		return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
	}
	s, err := loadStore(dir)
	if err != nil {
		return err
	}
	if _, ok := s.Customers[customerID]; !ok {
		return fmt.Errorf("客户标识 %q 不存在", customerID)
	}
	if _, ok := s.Bills[billKey(customerID, month)]; !ok {
		return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
	}

	// 截止序号省略表示最新（存档全局序号上限）；0 只返回初始余额；
	// 截止包含该序号本身。
	cutoff := s.NextSeq
	if cutoffText != "" {
		v, err := parseCutoffSeq(cutoffText)
		if err != nil {
			return err
		}
		if v > s.NextSeq {
			return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d，拒绝查询", v, s.NextSeq)
		}
		cutoff = v
	}

	report, err := buildLedger(s, customerID, month, cutoff)
	if err != nil {
		return err
	}
	printLedger(report)
	return nil
}

// parseCutoffSeq 解析截止操作序号：只接受非负整数；负数、小数或其他
// 非整数内容一律拒绝（超过存档上限由调用方判断）。
func parseCutoffSeq(text string) (int64, error) {
	text = strings.TrimSpace(text)
	v, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("截止操作序号 %q 必须是非负整数（0 只返回初始余额，省略表示最新）: %w", text, err)
	}
	if v < 0 {
		return 0, fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
	}
	return v, 0
}

// printLedger 渲染对账流水报告。
func printLedger(r *ledgerReport) {
	fmt.Fprintln(stdout, "账后对账流水")
	fmt.Fprintf(stdout, "账单标识：%s\n", r.bill.ID)
	fmt.Fprintf(stdout, "客户：%s（%s）\n", r.cust.ID, r.cust.Name)
	fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", r.bill.Month)
	fmt.Fprintf(stdout, "原总金额：%d 分（%s）——账后流水起点（初始应付，初始实收为 0）\n",
		r.bill.TotalFee, moneyFen(r.bill.TotalFee))
	fmt.Fprintf(stdout, "存档全局序号上限：%d\n", r.maxSeq)
	fmt.Fprintf(stdout, "查询截止序号：%d%s\n", r.cutoff, cutoffNote(r))
	if len(r.events) == 0 {
		fmt.Fprintln(stdout, "流水：空（截止以内没有调整、收款或其撤销事件）")
	} else {
		fmt.Fprintln(stdout, "流水（按成功操作序号升序，截止包含该序号）：")
		for i, ev := range r.events {
			fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(r, ev))
		}
	}
	fmt.Fprintln(stdout, "截止时余额：")
	fmt.Fprintf(stdout, "  应付：%d 分（%s）\n", r.final.payable, moneyFen(r.final.payable))
	fmt.Fprintf(stdout, "  实收：%d 分（%s）\n", r.final.received, moneyFen(r.final.received))
	fmt.Fprintf(stdout, "  未收余额：%d 分（%s）\n", r.final.outstanding, moneyFen(r.final.outstanding))
}

func cutoffNote(r *ledgerReport) string {
	switch {
	case r.cutoff == 0:
		return "（0：只返回初始余额）"
	case r.cutoff >= r.maxSeq:
		return "（最新）"
	default:
		return ""
	}
}

// formatLedgerEvent 渲染单个事件：序号、类型、原记录标识、金额影响、
// 原因/备注、撤销关联，以及事件后的应付/实收/未收余额。
func formatLedgerEvent(r *ledgerReport, ev *ledgerEvent) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "序号=%d 类型=%s 原记录=%s", ev.seq, ledgerKindName(ev.kind), ev.recordID)
	switch ev.kind {
	case evAdjust:
		fmt.Fprintf(&sb, " 金额影响：应付 %+d 分（%s）", ev.dPayable, moneyFen(ev.dPayable))
	case evAdjustRevoke:
		fmt.Fprintf(&sb, " 金额影响：应付 %+d 分（%s）", ev.dPayable, moneyFen(ev.dPayable))
	case evPayment:
		fmt.Fprintf(&sb, " 汇款总额=%d 分（%s） 本账单分配=%d 分（%s） 金额影响：实收 +%d 分",
			ev.payTotal, moneyFen(ev.payTotal), ev.dReceived, moneyFen(ev.dReceived), ev.dReceived)
	case evPaymentRevoke:
		fmt.Fprintf(&sb, " 汇款总额=%d 分（%s） 本账单分配=%d 分（%s） 金额影响：实收 %+d 分（整笔撤销在同一序号取消该分配）",
			ev.payTotal, moneyFen(ev.payTotal), -ev.dReceived, moneyFen(-ev.dReceived), ev.dReceived)
	}
	if ev.reason != "" {
		fmt.Fprintf(&sb, " %s：%s", ledgerReasonLabel(ev.kind), ev.reason)
	}
	switch {
	case ev.kind == evAdjust || ev.kind == evPayment:
		if ev.revokeSeq > 0 {
			if ev.revokeSeq <= r.cutoff {
				fmt.Fprintf(&sb, " 撤销关联：已于序号 %d 撤销（原因见该撤销事件）", ev.revokeSeq)
			} else {
				// 截止之后的撤销如实标注，但不影响本次历史余额，其撤销事件也不混入流水。
				fmt.Fprintf(&sb, " 撤销关联：存档中于序号 %d 撤销（发生在截止之后，不影响本次历史余额）", ev.revokeSeq)
			}
		}
	case ev.kind == evAdjustRevoke || ev.kind == evPaymentRevoke:
		fmt.Fprintf(&sb, " 撤销关联：抵消序号 %d 的%s（原记录 %s）",
			ev.originSeq, ledgerKindName(ev.originKind), ev.recordID)
	}
	fmt.Fprintf(&sb, " | 事件后：应付=%d 分 实收=%d 分 未收=%d 分",
		ev.post.payable, ev.post.received, ev.post.outstanding)
	return sb.String()
}

func ledgerKindName(k ledgerEventKind) string {
	switch k {
	case evAdjust:
		return "调整"
	case evAdjustRevoke:
		return "调整撤销"
	case evPayment:
		return "收款"
	case evPaymentRevoke:
		return "收款撤销"
	default:
		return "未知"
	}
}

func ledgerReasonLabel(k ledgerEventKind) string {
	switch k {
	case evAdjust:
		return "原因"
	case evAdjustRevoke, evPaymentRevoke:
		return "撤销原因"
	case evPayment:
		return "备注"
	default:
		return "说明"
	}
}

