16	//
17	// 关键规则：
18	//   - 调整只改变应付；收款只按其在本账单的分配改变实收；
19	//   - 撤销在其发生序号抵消对应原操作：已撤销记录在撤销之前仍须计入，
20	//     不能按当前撤销状态提前扣除或删除原事件；
21	//   - 每个事件后都必须满足 0 ≤ 实收 ≤ 应付 ≤ MaxInt64，不只检查最终余额；
22	//   - 查询前核验目标账单的完整流水，异常即使发生在截止序号之后也拒绝；
23	//   - 查询只读：绝不落盘、不占用序号、不新增记录。
24	
25	// ledgerEventKind 描述流水事件类型。
26	type ledgerEventKind int
27	
28	const (
29		evAdjust        ledgerEventKind = iota // 调整登记
30		evAdjustRevoke                         // 调整撤销
31		evPayment                              // 收款登记
32		evPaymentRevoke                        // 收款撤销
33	)
34	
35	// ledgerEvent 是合并后流水中的一个条目。
36	type ledgerEvent struct {
37		seq       int64
38		kind      ledgerEventKind
39		recordID  string // 原记录标识（调整/收款自身的标识）
40		dPayable  int64  // 对应付的影响：调整 ±amount；其余为 0
41		dReceived int64  // 对实收的影响：收款 +本账单分配；撤销为 -原影响
42		reason    string // 登记原因/备注，或撤销原因
43		payTotal  int64  // 收款类事件的汇款总额；其余为 0
44	
45		revokeSeq  int64           // 原操作事件：撤销发生序号（0 表示存档中未撤销）
46		originSeq  int64           // 撤销事件：被抵消原操作的序号
47		originKind ledgerEventKind // 撤销事件：被抵消原操作的类型
48	
49		post ledgerSnapshot // 事件后余额（cutoff 回放时写入）
50	}
51	
52	// ledgerSnapshot 是某个时点该账单的三项余额。
53	type ledgerSnapshot struct {
54		payable     int64
55		received    int64
56		outstanding int64
57	}
58	
59	// ledgerReport 是一次流水查询的结果。
60	type ledgerReport struct {
61		bill     *bill
62		cust     *customer
63		maxSeq   int64 // 存档全局序号上限（state.NextSeq）
64		cutoff   int64 // 查询采用的截止序号（省略等于 maxSeq；0 只看初始余额）
65		explicit bool  // 截止序号是否由命令行显式给出（影响“最新/只看初始”标注）
66		events   []*ledgerEvent
67		final    ledgerSnapshot
68	}
69	
70	// buildLedger 构建并核验目标账单的完整账后流水，再按 cutoff 回放。
71	func buildLedger(s *state, customerID, month string, cutoff int64) (*ledgerReport, error) {
72		b, ok := s.Bills[billKey(customerID, month)]
73		if !ok {
74			return nil, fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
75		}
76		cust := s.Customers[customerID] // loadStore 已校验存在
77	
78		adjs := adjustmentsFor(s, customerID, month)
79		pays := paymentsFor(s, customerID, month)
80	
81		// 1) 全局序号占用核验：序号重复一律拒绝（即使 loadStore.validate 已查过，
82		//    流水核验不依赖这一前提）。
83		if err := checkGlobalSeqOwners(s); err != nil {
84			return nil, err
85		}
86	
87		// 2) 收集本账单的全部事件到 序号 -> 事件 映射。其他客户/月份造成的
88		//    序号空档不进入映射，回放时自然跳过，属合法。
89		events := make(map[int64]*ledgerEvent)
90		addEvent := func(ev *ledgerEvent) error {
91			if ev.seq < 1 || ev.seq > s.NextSeq {
92				return fmt.Errorf("操作序号 %d（%s）越出存档序号范围 [1, %d]，流水引用失效",
93					ev.seq, ledgerEventName(ev.kind, ev.recordID), s.NextSeq)
94			}
95			if prev, dup := events[ev.seq]; dup {
96				return fmt.Errorf("操作序号 %d 重复：%s 与 %s", ev.seq,
97					ledgerEventName(prev.kind, prev.recordID), ledgerEventName(ev.kind, ev.recordID))
98			}
99			events[ev.seq] = ev
100			return nil
101		}
102	
103		for _, a := range adjs {
104			if err := addEvent(&ledgerEvent{
105				seq:       a.Seq,
106				kind:      evAdjust,
107				recordID:  a.ID,
108				dPayable:  a.Amount,
109				reason:    a.Reason,
110				revokeSeq: a.revokeSeqOrZero(),
111			}); err != nil {
112				return nil, err
113			}
114		}
115		for _, a := range adjs {
116			if !a.Revoked {
117				continue
118			}
119			// 撤销先于原操作（或同序号）拒绝。
120			if a.RevokeSeq <= a.Seq {
121				return nil, fmt.Errorf("调整 %q 的撤销序号 %d 不晚于原操作序号 %d，撤销引用失效",
122					a.ID, a.RevokeSeq, a.Seq)
123			}
124			neg, err := neg64(a.Amount)
125			if err != nil {
126				return nil, fmt.Errorf("调整 %q 金额 %d 取反超出有符号 64 位整数范围，流水无法核验", a.ID, a.Amount)
127			}
128			if err := addEvent(&ledgerEvent{
129				seq:        a.RevokeSeq,
130				kind:       evAdjustRevoke,
131				recordID:   a.ID,
132				dPayable:   neg,
133				reason:     a.RevokeReason,
134				originSeq:  a.Seq,
135				originKind: evAdjust,
136			}); err != nil {
137				return nil, err
138			}
139		}
140		for _, p := range pays {
141			alloc := p.amountFor(month)
142			if err := addEvent(&ledgerEvent{
143				seq:       p.Seq,
144				kind:      evPayment,
145				recordID:  p.ID,
146				dReceived: alloc,
147				reason:    p.Note,
148				payTotal:  p.Total,
149				revokeSeq: p.revokeSeqOrZero(),
150			}); err != nil {
151				return nil, err
152			}
153		}
154		for _, p := range pays {
155			if !p.Revoked {
156				continue
157			}
158			if p.RevokeSeq <= p.Seq {
159				return nil, fmt.Errorf("收款 %q 的撤销序号 %d 不晚于原操作序号 %d，撤销引用失效",
160					p.ID, p.RevokeSeq, p.Seq)
161			}
162			alloc := p.amountFor(month)
163			if err := addEvent(&ledgerEvent{
164				seq:        p.RevokeSeq,
165				kind:       evPaymentRevoke,
166				recordID:   p.ID,
167				dReceived:  -alloc, // 整笔撤销在同一序号取消该账单分配
168				reason:     p.RevokeReason,
169				payTotal:   p.Total,
170				originSeq:  p.Seq,
171				originKind: evPayment,
172			}); err != nil {
173				return nil, err
174			}
175		}
176	
177		// 3) 撤销引用的原操作必须能在本账单流水中找到（引用失效拒绝）。
178		for _, a := range adjs {
179			if a.Revoked {
180				if _, ok := events[a.Seq]; !ok {
181					return nil, fmt.Errorf("调整 %q 的撤销找不到原操作（序号 %d），引用失效", a.ID, a.Seq)
182				}
183			}
184		}
185		for _, p := range pays {
186			if p.Revoked {
187				if _, ok := events[p.Seq]; !ok {
188					return nil, fmt.Errorf("收款 %q 的撤销找不到原操作（序号 %d），引用失效", p.ID, p.Seq)
189				}
190			}
191		}
192	
193		ordered := sortLedgerEvents(events)
194	
195		// 4) 先回放“完整流水”逐事件核验不变量：异常即使在 cutoff 之后也拒绝。
196		//    累计补收或收款发生额本身可能超过 MaxInt64，只要每一步余额合法即通过。
197		snap := ledgerSnapshot{payable: b.TotalFee, received: 0, outstanding: b.TotalFee}
198		if snap.payable < 0 {
199			return nil, fmt.Errorf("账单 %s 原总金额为负（%d），流水无法核验", b.ID, snap.payable)
200		}
201		for _, ev := range ordered {
202			next, err := applyLedgerEvent(snap, ev)
203			if err != nil {
204				return nil, fmt.Errorf("完整流水核验失败：序号 %d（%s）之后余额不合法：%w",
205					ev.seq, ledgerEventName(ev.kind, ev.recordID), err)
206			}
207			snap = next
208		}
209	
210		// 5) 按 cutoff 回放历史：截止包含该序号；截止之后的事件既不影响历史
211		//    余额，也不混入流水。
212		shown := make([]*ledgerEvent, 0, len(ordered))
213		hist := ledgerSnapshot{payable: b.TotalFee, received: 0, outstanding: b.TotalFee}
214		for _, ev := range ordered {
215			if ev.seq > cutoff {
216				break
217			}
218			next, err := applyLedgerEvent(hist, ev)
219			if err != nil {
220				return nil, fmt.Errorf("序号 %d 回放失败：%w", ev.seq, err) // 理论不可达：第 4 步已核验
221			}
222			hist = next
223			ev.post = hist
224			shown = append(shown, ev)
225		}
226	
227		return &ledgerReport{
228			bill:   b,
229			cust:   cust,
230			maxSeq: s.NextSeq,
231			cutoff: cutoff,
232			events: shown,
233			final:  hist,
234		}, nil
235	}
236	
237	// revokeSeqOrZero 返回记录的撤销序号；未撤销时为 0。
238	func (a *adjustment) revokeSeqOrZero() int64 {
239		if a.Revoked {
240			return a.RevokeSeq
241		}
242		return 0
243	}
244	
245	func (p *payment) revokeSeqOrZero() int64 {
246		if p.Revoked {
247			return p.RevokeSeq
248		}
249		return 0
250	}
251	
252	// checkGlobalSeqOwners 核验全库调整/收款及其撤销的序号互不重复、均落在
253	// [1, NextSeq] 内。loadStore.validate 已做同等检查，这里再独立核验一遍，
254	// 使流水查询不依赖“载入时一定校验过”的假设。
255	func checkGlobalSeqOwners(s *state) error {
256		owner := make(map[int64]string)
257		claim := func(seq int64, who string) error {
258			if seq < 1 || seq > s.NextSeq {
259				return fmt.Errorf("%s 的操作序号 %d 越出存档序号范围 [1, %d]，引用失效", who, seq, s.NextSeq)
260			}
261			if prev, dup := owner[seq]; dup {
262				return fmt.Errorf("操作序号 %d 重复：%s 与 %s", seq, prev, who)
263			}
264			owner[seq] = who
265			return nil
266		}
267		// 遍历顺序不确定，但只用于发现重复/越界，与顺序无关。
268		for id, a := range s.Adjustments {
269			if err := claim(a.Seq, "调整 "+id); err != nil {
270				return err
271			}
272			if a.Revoked {
273				if err := claim(a.RevokeSeq, "撤销调整 "+id); err != nil {
274					return err
275				}
276			}
277		}
278		for id, p := range s.Payments {
279			if err := claim(p.Seq, "收款 "+id); err != nil {
280				return err
281			}
282			if p.Revoked {
283				if err := claim(p.RevokeSeq, "撤销收款 "+id); err != nil {
284					return err
285				}
286			}
287		}
288		return nil
289	}
