291	// sortLedgerEvents 按序号升序返回事件。
292	func sortLedgerEvents(events map[int64]*ledgerEvent) []*ledgerEvent {
293		out := make([]*ledgerEvent, 0, len(events))
294		for _, ev := range events {
295			out = append(out, ev)
296		}
297		sort.Slice(out, func(i, j int) bool { return out[i].seq < out[j].seq })
298		return out
299	}
300	
301	// applyLedgerEvent 把单个事件作用到余额上，全程有符号 64 位整数运算，
302	// 事件后校验 0 ≤ 实收 ≤ 应付 ≤ MaxInt64。
303	func applyLedgerEvent(cur ledgerSnapshot, ev *ledgerEvent) (ledgerSnapshot, error) {
304		payable, err := addSigned64(cur.payable, ev.dPayable)
305		if err != nil {
306			return ledgerSnapshot{}, fmt.Errorf("应付运算溢出（%d %+d）", cur.payable, ev.dPayable)
307		}
308		received, err := addSigned64(cur.received, ev.dReceived)
309		if err != nil {
310			return ledgerSnapshot{}, fmt.Errorf("实收运算溢出（%d %+d）", cur.received, ev.dReceived)
311		}
312		if payable < 0 || payable > int64Max {
313			return ledgerSnapshot{}, fmt.Errorf("应付 %d 越出 [0, %d]", payable, int64Max)
314		}
315		if received < 0 {
316			return ledgerSnapshot{}, fmt.Errorf("实收 %d 小于 0（应付 %d）", received, payable)
317		}
318		if received > payable {
319			return ledgerSnapshot{}, fmt.Errorf("实收 %d 超过应付 %d", received, payable)
